
(()=>{'use strict';
const ART={"shahada":"data:image/webp;base64,","salat":"data:image/webp;base64,","zakat":"data:image/webp;base64,","sawm":"data:image/webp;base64,","hajj":"data:image/webp;base64,","patio-mezkita":"data:image/webp;base64,","paisaje-panoramico":"data:image/webp;base64,","arco-icono":"data:image/webp;base64,"};
const ROOT='p10-root',KEY='islama-v4-puntuazioak',TIME=90;
const LABELS=['Shahada','Salat','Zakat','Sawm','Hajj'];
// All five definitions are based on PDF slide 8; names are the teacher's required terminology.
const Q=[
{id:'shahada',name:'Shahada',text:'«Jainko bakarra Ala da eta Mahoma haren profeta» onartzea.',page:8},
{id:'salat',name:'Salat',text:'Mekara zuzendutako otoitza eta ostiraleko komunitatearen otoitza mezkitan egitea.',page:8},
{id:'zakat',name:'Zakat',text:'Behartsuei limosna ematea.',page:8},
{id:'sawm',name:'Sawm',text:'Ramadan hilean barau egitea, eguzkia ateratzen denetik ezkutatu arte.',page:8},
{id:'hajj',name:'Hajj',text:'Mekara bizitzan behin erromes joatea.',page:8},
];
let root=null,game=null,timer=null,sound=true,busy=false,justClicked=false;
const el=id=>root?.querySelector('#'+id);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shuffle=arr=>{arr=[...arr];for(let i=arr.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[arr[i],arr[j]]=[arr[j],arr[i]];}return arr;};
function readScores(){try{return JSON.parse(localStorage.getItem(KEY))||{}}catch{return {}}}
function ranking(){const vals=Object.values(readScores().bost||{});return vals.sort((a,b)=>b.score-a.score||a.timestamp-b.timestamp).slice(0,10)}
function save(score){let all=readScores();all.bost||={};const id=game.nick.toLocaleLowerCase('eu');if(!all.bost[id]||all.bost[id].score<score){all.bost[id]={name:game.nick,score,timestamp:Date.now()};try{localStorage.setItem(KEY,JSON.stringify(all));return true}catch{return false}}return true}
function rankHTML(){const list=ranking();el('p10-ranking').innerHTML=list.length?list.map((r,i)=>`<div class="p10-rank-row"><span>${i+1}.</span><span>${esc(r.name)}</span><span>${Number(r.score).toLocaleString('eu-ES')}</span></div>`).join(''):'<p class="p10-empty">Oraindik ez dago puntuaziorik.<br>Izan zaitez lehena!</p>'}
function audio(ok){if(!sound)return;try{const C=window.AudioContext||window.webkitAudioContext;let c=new C(),o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.value=ok?680:250;g.gain.value=.035;o.connect(g).connect(c.destination);o.start();o.stop(c.currentTime+.14);setTimeout(()=>c.close(),350)}catch{}}
function shell(){const cards=Q.map(q=>`<button class="p10-pillar" data-pillar="${q.id}" aria-label="${q.name}" type="button"><img class="p10-art" src="${ART[q.id]}" alt="${q.name} irudikatzen duen ilustrazioa"><span class="p10-label">${q.name}</span></button>`).join('');const nav=Array.from({length:10},(_,i)=>`<button ${i===2?'class="active"':''} data-nav="${i+1}" aria-label="${i+1}. jokoa">${i+1}</button>`).join('');return `<div id="p10-root" hidden lang="eu" style="--p10-panorama:url('${ART['paisaje-panoramico']}')"><div class="p10-shell">
<header class="p10-hud"><button class="p10-royal p10-home" data-action="home" aria-label="Hasierara itzuli">⌂</button><div class="p10-royal p10-title">3. Islamaren bost zutabeak</div><div class="p10-hearts" id="p10-hearts">❤️❤️❤️</div><div class="p10-hud-pill" id="p10-score">Puntuak: 0</div><div class="p10-hud-pill" id="p10-clock">⏱ 01:30</div><button class="p10-royal p10-audio" data-action="sound" id="p10-sound" aria-label="Soinua piztu edo itzali">🔊</button></header>
<div class="p10-main"><aside class="p10-left p10-side p10-parchment"><div class="p10-medal">3.<br>JOKOA</div><h2>Zutabeen<br>erronka</h2><img class="p10-icon" src="${ART['arco-icono']}" alt=""><p>Lotu zutabe bakoitza bere esanahiarekin.</p><div class="p10-progress" id="p10-progress">0/5</div><div class="p10-tip"><strong>💡 Aholkua</strong><span>Irakurri ongi esanahia eta aukeratu dagokion zutabea.</span><small>PDF: 8. orrialdea</small></div></aside>
<section class="p10-center" aria-label="Bost zutabeak"><div class="p10-sky-title">Ezagutu bost zutabeak eta erantzun galderak!</div><div class="p10-grid" id="p10-cards">${cards}</div><div class="p10-question"><button type="button" data-action="prevq" aria-label="Aurreko galdera">❮</button><p id="p10-question">Behartsuei limosna ematea.</p><button type="button" data-action="nextq" aria-label="Hurrengo galdera">❯</button></div><div class="p10-feedback" id="p10-feedback" role="status" aria-live="polite">Aukeratu dagokion zutabea.</div></section>
<aside class="p10-right p10-side p10-parchment"><div class="p10-rank-head">🏆 TOP 10</div><div id="p10-ranking"></div><div class="p10-rank-local">Ordenagailu honetako sailkapena</div></aside></div>
<footer class="p10-footer"><button class="p10-nav" data-action="prevgame">❮ Aurrekoa</button><div class="p10-index">${nav}</div><button class="p10-nav" data-action="nextgame">Hurrengoa ❯</button></footer>
<div class="p10-overlay" id="p10-start"><form class="p10-dialog p10-parchment" id="p10-form"><h2>Islamaren bost zutabeak</h2><p>Bost zutabeak ezagutzen dituzu? Hautatu zutabe zuzena!</p><label for="p10-name">Zure goitizena</label><input id="p10-name" name="goitizena" maxlength="18" autocomplete="off" placeholder="Adibidez: Ikasle7" required><div class="p10-invalid" id="p10-invalid"></div><button type="submit" class="p10-primary">▶ Jolastu</button><button type="button" class="p10-secondary" data-action="home">Hasierara</button></form></div>
<div class="p10-overlay" id="p10-end" hidden><div class="p10-dialog p10-parchment"><h2 id="p10-end-title">Zorionak!</h2><p id="p10-end-description"></p><button class="p10-primary" data-action="again">↻ Berriro jokatu</button><button class="p10-secondary" data-action="home">Jokoen menura</button></div></div>
</div></div>`}
function launch(){if(!root){document.body.insertAdjacentHTML('beforeend',shell());root=document.getElementById(ROOT);root.addEventListener('click',onClick);el('p10-form').addEventListener('submit',e=>{e.preventDefault();begin(el('p10-name').value)});document.addEventListener('keydown',onKeyDown);}root.hidden=false;document.body.style.overflow='hidden';game=null;busy=false;el('p10-start').hidden=false;el('p10-end').hidden=true;el('p10-feedback').textContent='Aukeratu dagokion zutabea.';el('p10-feedback').className='p10-feedback';el('p10-progress').textContent='0/5';try{el('p10-name').value=localStorage.getItem('pillars-v10-nick')||''}catch{}rankHTML();setTimeout(()=>el('p10-name').focus(),80)}
function close(){if(timer){clearInterval(timer);timer=null;}if(root)root.hidden=true;document.body.style.overflow='';game=null;busy=false}
function begin(nick){nick=nick.trim().normalize('NFC');if(!/^[\p{L}\p{N}_ -]{2,18}$/u.test(nick)){el('p10-invalid').textContent='Idatzi 2 eta 18 karaktere arteko goitizena.';return false}try{localStorage.setItem('pillars-v10-nick',nick)}catch{}if(timer)clearInterval(timer);game={nick,questions:shuffle(Q.map(q=>q.id)),current:0,solved:new Set(),lives:3,time:TIME,score:0,errors:0,finished:false,started:true};el('p10-start').hidden=true;el('p10-end').hidden=true;busy=false;el('p10-invalid').textContent='';render();timer=setInterval(()=>{if(!game||game.finished)return;game.time=Math.max(0,game.time-1);renderHUD();if(game.time===0)finish('Denbora agortu da!')},1000);return true}
function pending(){return game?.questions.filter(id=>!game.solved.has(id))||[]}
function activeQ(){let ps=pending();if(!ps.length)return null;game.current=Math.min(Math.max(0,game.current),ps.length-1);return Q.find(q=>q.id===ps[game.current]);}
function renderHUD(){if(!game)return;el('p10-hearts').textContent='❤️'.repeat(game.lives)+'🖤'.repeat(3-game.lives);el('p10-score').textContent='Puntuak: '+game.score.toLocaleString('eu-ES');el('p10-clock').textContent='⏱ '+String(Math.floor(game.time/60)).padStart(2,'0')+':'+String(game.time%60).padStart(2,'0')}
function render(){if(!game)return;const q=activeQ();el('p10-progress').textContent=game.solved.size+'/5';el('p10-question').textContent=q?.text||'Zorionak!';root.querySelectorAll('[data-pillar]').forEach(b=>{const done=game.solved.has(b.dataset.pillar);b.classList.toggle('correct',done);b.disabled=done||game.finished; b.setAttribute('aria-pressed',done?'true':'false')});renderHUD();rankHTML()}
function currentIndexShift(dir){if(!game||game.finished||busy)return;let ps=pending();if(!ps.length)return;game.current=(game.current+dir+ps.length)%ps.length;el('p10-feedback').textContent='Aukeratu dagokion zutabea.';el('p10-feedback').className='p10-feedback';render()}
function answer(id){if(!game||game.finished||busy||game.solved.has(id))return;const q=activeQ();if(!q)return;busy=true;const b=root.querySelector(`[data-pillar="${id}"]`);let ok=id===q.id;if(ok){game.solved.add(id);game.score=Math.min(1000,game.solved.size*180);el('p10-feedback').textContent='Bikain! Erantzun zuzena!';el('p10-feedback').className='p10-feedback good';audio(true);}else{game.errors++;game.lives=Math.max(0,game.lives-1);b.classList.add('wrong');el('p10-feedback').textContent='Ez da zuzena. Saiatu berriro!';el('p10-feedback').className='p10-feedback bad';audio(false)}render();const answeredRound=game;setTimeout(()=>{if(game!==answeredRound)return;b.classList.remove('wrong');if(!game)return;if(!game.lives){finish('Bizitza guztiak galdu dituzu.');return}if(game.solved.size===5){game.score=Math.min(1000,900+Math.round(100*game.time/TIME));finish('Zorionak! Bost zutabeak ezagutu dituzu!');return}if(ok){game.current=0;el('p10-feedback').textContent='Jarraitu hurrengo erronkarekin!';el('p10-feedback').className='p10-feedback'}busy=false;render()},650)}
function finish(message){if(!game||game.finished)return;game.finished=true;busy=false;if(timer){clearInterval(timer);timer=null}const won=game.solved.size===5&&game.time>0&&game.lives>0;const stored=won?save(game.score):false;rankHTML();renderHUD();el('p10-end-title').textContent=game.solved.size===5?'🏆 Zorionak!':'Partida amaitu da';el('p10-end-description').textContent=`${message} Puntuak: ${game.score.toLocaleString('eu-ES')} · Zuzenak: ${game.solved.size}/5 · Akatsak: ${game.errors} · ${won?(stored?'Marka osatua: TOP 10 lokala eguneratu da.':'Partida amaituta, baina ezin izan da errekorra gorde.'):'Amaitu gabeko partida: ez da errekorretan gorde.'}`;el('p10-end').hidden=false}
function navigate(n){const name=({1:'arabia',2:'denbora',4:'hedapena',5:'kalifaldi',6:'gizartea',7:'hiria',8:'merkataritza',9:'artea',10:'ondarea'})[n];if(n===3)return;close();if(name){const target=document.querySelector(`#game-gallery [data-game="${name}"]`);if(target)target.click();}}
function onClick(e){const action=e.target.closest('[data-action]')?.dataset.action;if(action){if(action==='home'){close()}else if(action==='sound'){sound=!sound;el('p10-sound').textContent=sound?'🔊':'🔇'}else if(action==='prevq')currentIndexShift(-1);else if(action==='nextq')currentIndexShift(1);else if(action==='again'){const name=game?.nick||el('p10-name').value;begin(name)}else if(action==='prevgame')navigate(2);else if(action==='nextgame')navigate(4);return;}const nav=e.target.closest('[data-nav]');if(nav){navigate(Number(nav.dataset.nav));return}const b=e.target.closest('[data-pillar]');if(b)answer(b.dataset.pillar)}
function onKeyDown(e){if(!root||root.hidden)return;if(e.key==='Escape'){if(!el('p10-start').hidden||!el('p10-end').hidden)close()} }
window.PILLARS_V10={launch,close,testStart:(name='Proba33')=>{launch();return begin(name)},getState:()=>game?{...game,solved:[...game.solved]}:null,answerForTest:answer,nextQuestionForTest:()=>currentIndexShift(1),getRankingForTest:ranking};
})();
